const assert = require('node:assert');
const path = require('node:path');
const { finalPrice, getDiscountRate } = require(path.resolve(process.argv[2]));

// The reported bug: an unknown code must charge full price, not NaN.
assert.strictEqual(finalPrice(100, 'BOGUS'), 100, 'unknown code should charge full price');
assert.strictEqual(getDiscountRate('BOGUS'), 0, 'unknown code should have a zero rate');

// Inherited Object members must also miss the lookup.
assert.strictEqual(finalPrice(100, 'toString'), 100, 'inherited key should charge full price');
assert.strictEqual(finalPrice(100, undefined), 100, 'missing code should charge full price');

// Known codes must keep working.
assert.strictEqual(finalPrice(100, 'SAVE10'), 90);
assert.strictEqual(finalPrice(100, 'SAVE20'), 80);
assert.strictEqual(finalPrice(100, 'HALFOFF'), 50);

console.log('all pricing assertions passed');

